def signal(D,W):
    s=np.linalg.svd(D,compute_uv=False)
    m,n=D.shape; 
    med=np.median(s)
    edge=med*(1+np.sqrt(min(m,n)/max(m,n)))/ (1-0.5*np.sqrt(min(m,n)/max(m,n))+1e-9) # rough bulk edge
    edge=1.8*med
    sig=np.sum(np.maximum(s**2-edge**2,0))
    return sig/np.sum(W**2)*1e4, int((s>edge).sum())
